{
  "name": "opencode-9router",
  "version": "0.1.1",
  "description": "OpenCode TUI companion for 9Router \u2014 usage by provider in the session sidebar, model picker with per-model thinking levels, and provider management dialogs.",
  "author": "mrrobot1o1 <mrrobot1o1@outlook.in>",
  "keywords": [
    "opencode",
    "opencode-plugin",
    "9router",
    "usage",
    "tui",
    "ai-router"
  ],
  "license": "MIT",
  "type": "module",
  "exports": {
    ".": "./server.ts",
    "./server": "./server.ts",
    "./tui": "./tui.tsx"
  },
  "main": "server.ts",
  "types": "server.ts",
  "files": [
    "src",
    "server.ts",
    "tui.tsx",
    "README.md",
    "LICENSE"
  ],
  "engines": {
    "opencode": "^2.0.0"
  },
  "scripts": {
    "check": "tsc --noEmit",
    "mock": "node scripts/mock-router.mjs"
  },
  "dependencies": {
    "@opencode/plugin": "^2.2.0"
  },
  "peerDependencies": {
    "@opentui/core": ">=0.6.6",
    "@opentui/solid": ">=0.6.6",
    "solid-js": ">=1.9.0"
  },
  "devDependencies": {
    "@opentui/core": ">=0.6.6",
    "@opentui/solid": ">=0.6.6",
    "solid-js": ">=1.9.0",
    "@types/node": "^22.0.0",
    "typescript": "^5.9.3"
  },
  "repository": {
    "type": "git",
    "url": "git+https://github.com/mrrobot1o1/opencode-9router.git"
  },
  "bugs": "https://github.com/mrrobot1o1/opencode-9router/issues",
  "homepage": "https://github.com/mrrobot1o1/opencode-9router#readme"
}
